#!/usr/bin/env python3\n\"\"\"\nFree Fire Pro Bot - Main Bot File\nA powerful Free Fire bot with anti-ban protection\n\"\"\"\n\nimport asyncio\nimport time\nimport random\nimport struct\nfrom typing import Optional, List, Dict\nfrom datetime import datetime\nfrom Crypto.Cipher import AES\nfrom Crypto.Random import get_random_bytes\n\n# ============================================================================\n# CONFIGURATION\n# ============================================================================\n\nCONFIG = {\n    'FF_SERVER_IP': 'localhost',  # غير هنا IP السيرفر\n    'FF_SERVER_PORT': 9339,       # غير هنا PORT السيرفر\n    'REGION': 'PK',               # المنطقة (PK, IN, BR, etc)\n    'BOT_UID': '415136165',       # UID البوت\n    'COMMAND_DELAY': 2.0,         # التأخير بين الأوامر (ثواني)\n    'MESSAGE_DELAY': 0.5,         # التأخير بين الرسائل (ثواني)\n    'EMOTE_DELAY': 1.0,           # التأخير بين الرقصات (ثواني)\n    'RECONNECT_DELAY': 5.0,       # تأخير إعادة الاتصال\n    'MAX_REQUESTS_PER_MINUTE': 30, # عدد الطلبات الأقصى\n}\n\n# ============================================================================\n# LOGGING\n# ============================================================================\n\ndef log(message: str, level: str = 'INFO'):\n    \"\"\"Simple logging function\"\"\"\n    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')\n    colors = {\n        'INFO': '\\033[92m',    # أخضر\n        'WARNING': '\\033[93m', # أصفر\n        'ERROR': '\\033[91m',   # أحمر\n        'DEBUG': '\\033[94m',   # أزرق\n    }\n    reset = '\\033[0m'\n    color = colors.get(level, '')\n    print(f\"{color}[{timestamp}] [{level}]{reset} {message}\")\n\n# ============================================================================\n# ENCRYPTION\n# ============================================================================\n\nclass Encryption:\n    \"\"\"Encryption/Decryption utilities\"\"\"\n    \n    @staticmethod\n    def encrypt_aes(data: bytes, key: bytes, iv: bytes) -> bytes:\n        \"\"\"Encrypt using AES-128-CBC\"\"\"\n        try:\n            cipher = AES.new(key, AES.MODE_CBC, iv)\n            padding_length = 16 - (len(data) % 16)\n            padded_data = data + bytes([padding_length] * padding_length)\n            return cipher.encrypt(padded_data)\n        except Exception as e:\n            log(f\"Encryption error: {e}\", 'ERROR')\n            return b''\n    \n    @staticmethod\n    def decrypt_aes(data: bytes, key: bytes, iv: bytes) -> bytes:\n        \"\"\"Decrypt using AES-128-CBC\"\"\"\n        try:\n            cipher = AES.new(key, AES.MODE_CBC, iv)\n            decrypted = cipher.decrypt(data)\n            padding_length = decrypted[-1]\n            return decrypted[:-padding_length]\n        except Exception as e:\n            log(f\"Decryption error: {e}\", 'ERROR')\n            return b''\n\n# ============================================================================\n# ANTI-BAN PROTECTION\n# ============================================================================\n\nclass RateLimiter:\n    \"\"\"Rate limiter for anti-ban\"\"\"\n    \n    def __init__(self, max_requests: int, window: int = 60):\n        self.max_requests = max_requests\n        self.window = window\n        self.requests = {}\n    \n    async def check(self, key: str = 'default') -> bool:\n        \"\"\"Check if request is allowed\"\"\"\n        now = time.time()\n        if key not in self.requests:\n            self.requests[key] = []\n        \n        # Clean old requests\n        self.requests[key] = [t for t in self.requests[key] if now - t < self.window]\n        \n        if len(self.requests[key]) < self.max_requests:\n            self.requests[key].append(now)\n            return True\n        return False\n    \n    async def wait_if_needed(self, key: str = 'default'):\n        \"\"\"Wait until request is allowed\"\"\"\n        while not await self.check(key):\n            await asyncio.sleep(0.1)\n\nrate_limiter = RateLimiter(CONFIG['MAX_REQUESTS_PER_MINUTE'])\n\nclass DelayManager:\n    \"\"\"Manages delays to avoid ban\"\"\"\n    \n    @staticmethod\n    async def command_delay():\n        delay = random.uniform(CONFIG['COMMAND_DELAY'] * 0.8, CONFIG['COMMAND_DELAY'] * 1.2)\n        await asyncio.sleep(delay)\n    \n    @staticmethod\n    async def message_delay():\n        delay = random.uniform(CONFIG['MESSAGE_DELAY'] * 0.8, CONFIG['MESSAGE_DELAY'] * 1.2)\n        await asyncio.sleep(delay)\n    \n    @staticmethod\n    async def emote_delay():\n        delay = random.uniform(CONFIG['EMOTE_DELAY'] * 0.8, CONFIG['EMOTE_DELAY'] * 1.2)\n        await asyncio.sleep(delay)\n    \n    @staticmethod\n    async def random_delay(min_delay: float = 0.5, max_delay: float = 2.0):\n        delay = random.uniform(min_delay, max_delay)\n        await asyncio.sleep(delay)\n\n# ============================================================================\n# TCP CONNECTION\n# ============================================================================\n\nclass TCPClient:\n    \"\"\"TCP connection manager\"\"\"\n    \n    def __init__(self, host: str, port: int, key: bytes = None, iv: bytes = None):\n        self.host = host\n        self.port = port\n        self.key = key or get_random_bytes(16)\n        self.iv = iv or get_random_bytes(16)\n        self.reader = None\n        self.writer = None\n        self.connected = False\n    \n    async def connect(self) -> bool:\n        \"\"\"Connect to server\"\"\"\n        try:\n            log(f\"جاري الاتصال بـ {self.host}:{self.port}...\", 'INFO')\n            self.reader, self.writer = await asyncio.wait_for(\n                asyncio.open_connection(self.host, self.port),\n                timeout=30\n            )\n            self.connected = True\n            log(f\"✅ تم الاتصال بـ {self.host}:{self.port}\", 'INFO')\n            return True\n        except Exception as e:\n            log(f\"❌ فشل الاتصال: {e}\", 'ERROR')\n            self.connected = False\n            return False\n    \n    async def send(self, data: bytes) -> bool:\n        \"\"\"Send data\"\"\"\n        if not self.connected or not self.writer:\n            return False\n        \n        try:\n            # Encrypt if key and IV available\n            encrypted = Encryption.encrypt_aes(data, self.key, self.iv) if self.key else data\n            packet = struct.pack('>H', len(encrypted)) + encrypted\n            \n            self.writer.write(packet)\n            await asyncio.wait_for(self.writer.drain(), timeout=10)\n            return True\n        except Exception as e:\n            log(f\"خطأ في الإرسال: {e}\", 'ERROR')\n            self.connected = False\n            return False\n    \n    async def receive(self, timeout: float = 10.0) -> Optional[bytes]:\n        \"\"\"Receive data\"\"\"\n        if not self.connected or not self.reader:\n            return None\n        \n        try:\n            header = await asyncio.wait_for(self.reader.readexactly(2), timeout=timeout)\n            packet_length = struct.unpack('>H', header)[0]\n            encrypted = await asyncio.wait_for(self.reader.readexactly(packet_length), timeout=timeout)\n            decrypted = Encryption.decrypt_aes(encrypted, self.key, self.iv) if self.key else encrypted\n            return decrypted\n        except asyncio.TimeoutError:\n            return None\n        except Exception as e:\n            log(f\"خطأ في الاستقبال: {e}\", 'ERROR')\n            self.connected = False\n            return None\n    \n    async def close(self):\n        \"\"\"Close connection\"\"\"\n        if self.writer:\n            self.writer.close()\n            await self.writer.wait_closed()\n        self.connected = False\n        log(\"تم إغلاق الاتصال\", 'INFO')\n\n# ============================================================================\n# FREE FIRE PROTOCOL\n# ============================================================================\n\nclass FFProtocol:\n    \"\"\"Free Fire protocol packets\"\"\"\n    \n    @staticmethod\n    def heartbeat() -> bytes:\n        \"\"\"Heartbeat packet\"\"\"\n        return bytes([0x00, 0x00, 0x00, 0x02, 0x00, 0x00])\n    \n    @staticmethod\n    def message(chat_id: str, message: str) -> bytes:\n        \"\"\"Message packet\"\"\"\n        try:\n            msg_bytes = message.encode('utf-8')\n            packet = bytearray([0x03])\n            packet.extend(chat_id.encode('utf-8')[:20])\n            packet.extend(struct.pack('>H', len(msg_bytes)))\n            packet.extend(msg_bytes)\n            return bytes(packet)\n        except:\n            return b''\n    \n    @staticmethod\n    def emote(target_uid: str, emote_id: int) -> bytes:\n        \"\"\"Emote packet\"\"\"\n        try:\n            packet = bytearray([0x04])\n            uid_bytes = target_uid.encode('utf-8')\n            packet.extend(struct.pack('>H', len(uid_bytes)))\n            packet.extend(uid_bytes)\n            packet.extend(struct.pack('>I', emote_id))\n            return bytes(packet)\n        except:\n            return b''\n\n# ============================================================================\n# MAIN BOT CLASS\n# ============================================================================\n\nclass FreeFireBot:\n    \"\"\"Main Free Fire Bot\"\"\"\n    \n    def __init__(self, uid: str, host: str = CONFIG['FF_SERVER_IP'], port: int = CONFIG['FF_SERVER_PORT']):\n        self.uid = uid\n        self.tcp = TCPClient(host, port)\n        self.running = False\n        self.key, self.iv = get_random_bytes(16), get_random_bytes(16)\n    \n    async def connect(self) -> bool:\n        \"\"\"Connect to Free Fire\"\"\"\n        return await self.tcp.connect()\n    \n    async def disconnect(self):\n        \"\"\"Disconnect from Free Fire\"\"\"\n        await self.tcp.close()\n        self.running = False\n    \n    async def send_message(self, chat_id: str, message: str) -> bool:\n        \"\"\"Send message\"\"\"\n        if not self.tcp.connected:\n            return False\n        \n        await rate_limiter.wait_if_needed(f\"msg_{chat_id}\")\n        await DelayManager.message_delay()\n        \n        packet = FFProtocol.message(chat_id, message)\n        if await self.tcp.send(packet):\n            log(f\"✅ تم إرسال الرسالة: {message[:30]}...\", 'INFO')\n            return True\n        return False\n    \n    async def send_emote(self, target_uid: str, emote_id: int) -> bool:\n        \"\"\"Send emote\"\"\"\n        if not self.tcp.connected:\n            return False\n        \n        await rate_limiter.wait_if_needed(f\"emote_{target_uid}\")\n        await DelayManager.emote_delay()\n        \n        packet = FFProtocol.emote(target_uid, emote_id)\n        if await self.tcp.send(packet):\n            log(f\"✅ تم إرسال الرقصة {emote_id} للاعب {target_uid}\", 'INFO')\n            return True\n        return False\n    \n    async def emote_spam(self, uids: List[str], emote_id: int, times: int = 1) -> int:\n        \"\"\"Send emote spam with anti-ban protection\"\"\"\n        success = 0\n        total = len(uids) * times\n        \n        log(f\"⏳ بدء إرسال {total} رقصة بـ حماية ضد الحظر...\", 'INFO')\n        \n        for uid in uids:\n            for i in range(times):\n                if await self.send_emote(uid, emote_id):\n                    success += 1\n                await DelayManager.emote_delay()\n            await DelayManager.random_delay(1.0, 2.0)\n        \n        log(f\"✅ اكتملت العملية: {success}/{total} نجحت\", 'INFO')\n        return success\n    \n    async def message_spam(self, chat_id: str, message: str, times: int = 1) -> int:\n        \"\"\"Send message spam with anti-ban protection\"\"\"\n        success = 0\n        \n        log(f\"⏳ بدء إرسال {times} رسالة بـ حماية ضد الحظر...\", 'INFO')\n        \n        for i in range(times):\n            if await self.send_message(chat_id, message):\n                success += 1\n            await DelayManager.message_delay()\n        \n        log(f\"✅ اكتملت العملية: {success}/{times} نجحت\", 'INFO')\n        return success\n    \n    async def keep_alive(self):\n        \"\"\"Keep connection alive\"\"\"\n        while self.running:\n            try:\n                packet = FFProtocol.heartbeat()\n                await self.tcp.send(packet)\n                await asyncio.sleep(30)\n            except Exception as e:\n                log(f\"خطأ في keep alive: {e}\", 'WARNING')\n                break\n\n# ============================================================================\n# INTERACTIVE CONSOLE\n# ============================================================================\n\nasync def interactive_console(bot: FreeFireBot):\n    \"\"\"Interactive console for bot commands\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"🤖 Free Fire Pro Bot - Interactive Console\")\n    print(\"=\"*60)\n    print(\"الأوامر المتاحة:\")\n    print(\"  1. message <chat_id> <message>     - إرسال رسالة\")\n    print(\"  2. spam <chat_id> <message> <times> - إرسال رسائل متكررة\")\n    print(\"  3. emote <uid> <emote_id> <times> - إرسال رقصة\")\n    print(\"  4. spray <uid> <emote_id> <times> - إرسال رقصات متكررة\")\n    print(\"  5. status                           - حالة البوت\")\n    print(\"  6. help                             - مساعدة\")\n    print(\"  7. exit                             - إغلاق\")\n    print(\"=\"*60 + \"\\n\")\n    \n    loop = asyncio.get_event_loop()\n    \n    def input_thread():\n        while bot.running:\n            try:\n                return input(\"\\n📝 أدخل الأمر: \").strip()\n            except:\n                pass\n        return None\n    \n    while bot.running:\n        command = await loop.run_in_executor(None, input_thread)\n        \n        if not command:\n            continue\n        \n        parts = command.split()\n        cmd = parts[0].lower() if parts else \"\"\n        \n        try:\n            if cmd == '1' or cmd == 'message':\n                if len(parts) >= 3:\n                    chat_id = parts[1]\n                    message = ' '.join(parts[2:])\n                    await bot.send_message(chat_id, message)\n                else:\n                    log(\"❌ استخدام: message <chat_id> <message>\", 'ERROR')\n            \n            elif cmd == '2' or cmd == 'spam':\n                if len(parts) >= 4:\n                    chat_id = parts[1]\n                    message = ' '.join(parts[2:-1])\n                    times = int(parts[-1])\n                    await bot.message_spam(chat_id, message, times)\n                else:\n                    log(\"❌ استخدام: spam <chat_id> <message> <times>\", 'ERROR')\n            \n            elif cmd == '3' or cmd == 'emote':\n                if len(parts) >= 3:\n                    uid = parts[1]\n                    emote_id = int(parts[2])\n                    times = int(parts[3]) if len(parts) > 3 else 1\n                    await bot.send_emote(uid, emote_id)\n                else:\n                    log(\"❌ استخدام: emote <uid> <emote_id> [times]\", 'ERROR')\n            \n            elif cmd == '4' or cmd == 'spray':\n                if len(parts) >= 3:\n                    uid = parts[1]\n                    emote_id = int(parts[2])\n                    times = int(parts[3]) if len(parts) > 3 else 1\n                    await bot.emote_spam([uid], emote_id, times)\n                else:\n                    log(\"❌ استخدام: spray <uid> <emote_id> [times]\", 'ERROR')\n            \n            elif cmd == '5' or cmd == 'status':\n                print(f\"\\n📊 Status:\")\n                print(f\"  UID: {bot.uid}\")\n                print(f\"  متصل: {'✅ نعم' if bot.tcp.connected else '❌ لا'}\")\n                print(f\"  البوت يعمل: {'✅ نعم' if bot.running else '❌ لا'}\\n\")\n            \n            elif cmd == '6' or cmd == 'help':\n                print(\"\\n\" + \"=\"*60)\n                print(\"المساعدة:\")\n                print(\"=\"*60)\n                print(\"الأوامر:\")\n                print(\"  message <chat_id> <text> - إرسال رسالة\")\n                print(\"  spam <chat_id> <text> <num> - إرسال رسائل متكررة\")\n                print(\"  emote <uid> <id> - إرسال رقصة\")\n                print(\"  spray <uid> <id> <num> - إرسال رقصات متكررة\")\n                print(\"  status - عرض الحالة\")\n                print(\"  exit - إغلاق\\n\")\n                print(\"ملاحظات:\")\n                print(\"  ✅ البوت يوفر حماية تلقائية ضد الحظر\")\n                print(\"  ✅ هناك تأخيرات عشوائية بين الأوامر\")\n                print(\"  ✅ معدل الطلبات محدود بـ 30 طلب/دقيقة\\n\")\n            \n            elif cmd == '7' or cmd == 'exit' or cmd == 'quit':\n                log(\"جاري الإغلاق...\", 'INFO')\n                bot.running = False\n                break\n            \n            else:\n                log(\"❌ أمر غير معروف. اكتب 'help' للمساعدة\", 'ERROR')\n        \n        except Exception as e:\n            log(f\"❌ خطأ: {e}\", 'ERROR')\n\n# ============================================================================\n# MAIN\n# ============================================================================\n\nasync def main():\n    \"\"\"Main function\"\"\"\n    print(\"\\n\" + \"=\"*60)\n    print(\"🔥 Free Fire Pro Bot v1.0\")\n    print(\"حماية متقدمة ضد الحظر\")\n    print(\"=\"*60 + \"\\n\")\n    \n    # Create bot\n    bot = FreeFireBot(CONFIG['BOT_UID'])\n    \n    # Connect\n    if not await bot.connect():\n        log(\"فشل الاتصال. تأكد من بيانات السيرفر\", 'ERROR')\n        return\n    \n    bot.running = True\n    \n    # Run keep alive and console\n    try:\n        await asyncio.gather(\n            bot.keep_alive(),\n            interactive_console(bot)\n        )\n    except KeyboardInterrupt:\n        log(\"تم إيقاف البوت\", 'WARNING')\n    finally:\n        await bot.disconnect()\n        print(\"\\n👋 شكراً لاستخدامك الروبوت!\\n\")\n\nif __name__ == \"__main__\":\n    try:\n        asyncio.run(main())\n    except KeyboardInterrupt:\n        print(\"\\n\\nتم الإيقاف بواسطة المستخدم\\n\")\n"